  ('tu-lun-pho-ga-bun-thang', 'approved', 'hoan-kiem', 'food', 'quick', 'Tư Lùn - Phở Gà & Bún Thang', 'Tư Lùn - Phở Gà & Bún Thang', null, 21.031178, 105.8493, '5 Phố Hàng Trống', 'Mo-Su 06:00-13:30, 15:00-23:00', array['food']::text[], array['localFood']::text[], 30, 40, 70, null, 'butter', 'Phở gà và bún thang — nước dùng gà thanh, bún thang nhiều topping thái sợi nhỏ.', 'Chicken pho and bún thang, a delicate Hanoi noodle soup topped with finely shredded egg, chicken and pork.', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, array['openstreetmap']::text[], 'Điểm nhanh từ OpenStreetMap; giá là ước tính theo loại quán — kiểm lại khi đi thực địa.', null, null, null),
