  ('ninex-pickelball-clb', 'approved', 'hoan-kiem', 'fun', 'quick', 'NineX Pickleball CLB', 'NineX Pickleball CLB', null, 21.029046, 105.875071, null, null, array['fun']::text[], array['groups']::text[], 60, 50, 150, null, 'teal', 'Sân pickleball cho thuê theo giờ — môn thể thao đang rất thịnh ở Hà Nội.', 'Pickleball courts for hire — the sport everyone in Hanoi is playing right now.', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, array['openstreetmap']::text[], 'Điểm nhanh từ OpenStreetMap; giá là ước tính theo loại quán — kiểm lại khi đi thực địa.', null, null, null),
  ('sua-ba-vi', 'approved', 'ba-vi', 'food', 'quick', 'Sữa Ba Vì', 'Sữa Ba Vì', null, 21.128606, 105.515058, null, null, array['food']::text[], array['localFood']::text[], 20, 20, 80, null, 'butter', 'Sữa tươi, sữa chua và bánh sữa là những món quà quen thuộc của vùng đồi Ba Vì. Đây là điểm dừng nhanh, dễ mang theo và phù hợp để nếm thử đặc sản địa phương.', 'Fresh milk, yoghurt and milk sweets are familiar specialities of the Ba Vì hills. This is an easy, quick stop for a local taste and a portable gift.', null, null, 'Một món đặc sản nhẹ nhàng, hợp để nghỉ giữa chặng hoặc mua làm quà sau chuyến đi.', 'A light local speciality for a mid-route break or an easy souvenir to take home.', 'Chụp các loại bánh sữa và chai sữa cạnh nhau, lấy nền là đồi cây hoặc quầy hàng địa phương.', 'Arrange the milk sweets and bottles together, with green hills or the local shop as the background.', 'Sản phẩm sữa tươi cần giữ lạnh. Kiểm tra hạn dùng và hỏi cách bảo quản nếu còn di chuyển lâu.', 'Fresh dairy needs to stay chilled. Check the expiry date and ask about storage if you still have a long journey.', null, null, null, null, null, null, null, null, null, null, null, null, array['openstreetmap']::text[], 'Điểm nhanh từ OpenStreetMap; giá là ước tính theo loại quán — kiểm lại khi đi thực địa.', null, null, null),
  ('huong-quynh-trau-ngon-36-mon', 'approved', 'ba-vi', 'food', 'quick', 'Hương Quỳnh - Trâu Ngon 36 Món', 'Hương Quỳnh - Trâu Ngon 36 Món', null, 21.21493, 105.403835, null, null, array['food']::text[], array['groups','localFood']::text[], 60, 120, 250, null, 'butter', 'Nhà hàng chuyên nhiều cách chế biến thịt trâu, phù hợp với nhóm muốn dùng một bữa đậm vị sau khi tham quan. Các món thường được gọi chung để cả bàn cùng thử.', 'A restaurant focused on buffalo dishes, suited to groups wanting a hearty meal after sightseeing. Dishes are typically ordered for the table to share.', null, null, 'Thịt trâu là lựa chọn đặc trưng của nhiều quán vùng ngoại thành và ngon nhất khi đi đông người để gọi được nhiều món.', 'Buffalo is a popular speciality around the outer districts and works best for groups who can share several preparations.', 'Chụp toàn bàn khi các món vừa được dọn lên; ánh sáng cạnh cửa sổ giúp món ăn trông tự nhiên hơn.', 'Photograph the whole table as the dishes arrive; window light will make the food look more natural.', 'Hỏi khẩu phần và giá trước khi gọi vì món thường bán theo đĩa hoặc theo trọng lượng.', 'Ask about portion size and price before ordering, as dishes may be sold by plate or by weight.', null, null, null, null, null, null, null, null, null, null, null, null, array['openstreetmap']::text[], 'Điểm nhanh từ OpenStreetMap; giá là ước tính theo loại quán — kiểm lại khi đi thực địa.', null, null, null),
  ('nha-hang-ban-cooc-garden', 'approved', 'ba-vi', 'food', 'quick', 'Nhà hàng Bản Coốc Garden', 'Nhà hàng Bản Coốc Garden', null, 21.066218, 105.325837, null, '24/7', array['food']::text[], array['groups']::text[], 60, 100, 250, null, 'butter', 'Không gian nhà hàng thích hợp để nghỉ chân và ăn trưa trong hành trình vòng quanh Ba Vì. Điểm này thuận tiện cho nhóm cần một bữa ngồi thoải mái thay vì ăn nhanh ven đường.', 'A comfortable restaurant stop for lunch during a loop around Ba Vì. It suits groups wanting a proper seated meal rather than a quick roadside bite.', null, null, 'Có thể dùng làm điểm nghỉ giữa hai chặng dài để cả nhóm ăn uống và sắp xếp lại lịch trình.', 'A practical break between longer legs, giving the group time to eat and reset the itinerary.', 'Ưu tiên góc bàn gần cây xanh hoặc khu vườn; chụp trước khi bàn có quá nhiều đồ dùng.', 'Choose a table near the greenery and take photos before the table becomes crowded with dishes.', 'Nếu đi nhóm đông, nên liên hệ trước và hỏi thời gian phục vụ món để không ảnh hưởng lịch trình.', 'For a large group, contact the restaurant first and ask about serving time so the meal does not delay the route.', null, null, null, null, null, null, null, null, null, null, null, null, array['openstreetmap']::text[], 'Điểm nhanh từ OpenStreetMap; giá là ước tính theo loại quán — kiểm lại khi đi thực địa.', null, null, null),
  ('nha-hang-quyet-coi', 'approved', 'ba-vi', 'food', 'quick', 'Nhà hàng Quyết Còi', 'Nhà hàng Quyết Còi', null, 21.138103, 105.299981, null, null, array['food']::text[], array['groups']::text[], 60, 100, 250, null, 'butter', 'Một điểm ăn uống địa phương phù hợp cho bữa trưa hoặc bữa chiều trong chuyến khám phá phía tây Ba Vì. Không gian quán hợp với nhóm bạn và gia đình muốn ngồi nghỉ lâu hơn.', 'A local meal stop for lunch or an early dinner while exploring western Ba Vì. It works for friends and families who want a longer rest.', null, null, 'Vị trí giúp chia nhỏ hành trình ở khu vực có các điểm tham quan nằm khá xa nhau.', 'Its location helps break up a route where attractions can be spread far apart.', 'Chụp món chính cùng rau và nước chấm để khung hình có nhiều màu sắc hơn.', 'Frame the main dish with herbs and dipping sauces for a more colourful table shot.', 'Thực đơn và giá có thể thay đổi; hỏi món nổi bật trong ngày và xác nhận giá trước khi gọi.', 'Menus and prices may change. Ask for the day’s recommendations and confirm prices before ordering.', null, null, null, null, null, null, null, null, null, null, null, null, array['openstreetmap']::text[], 'Điểm nhanh từ OpenStreetMap; giá là ước tính theo loại quán — kiểm lại khi đi thực địa.', null, null, null),
  ('nha-hang-k', 'approved', 'ba-vi', 'food', 'quick', 'Nhà hàng K', 'Nhà hàng K', null, 21.117207, 105.326552, null, null, array['food']::text[], array['groups']::text[], 60, 100, 250, null, 'butter', 'Quán ăn nằm trên tuyến tham quan Ba Vì, phù hợp để dừng chân dùng bữa và tránh nắng giữa ngày. Đây là lựa chọn thực tế khi lịch trình có nhiều chặng di chuyển bằng xe.', 'A meal stop along a Ba Vì touring route, useful for lunch and a break from the midday heat. It is practical on itineraries with several driving legs.', null, null, 'Một bữa nghỉ đúng lúc giúp hành trình đường núi dễ chịu hơn, nhất là khi đi cùng trẻ nhỏ hoặc người lớn tuổi.', 'A well-timed meal break makes a mountain-road itinerary easier, especially with children or older travellers.', 'Chọn góc đủ sáng và chụp món ăn từ trên xuống để ghi lại cả mâm cơm.', 'Find a bright spot and shoot from above to capture the whole shared meal.', 'Kiểm tra giờ mở cửa trong ngày và hỏi trước khả năng phục vụ nếu đoàn đông.', 'Check the day’s opening hours and ask about capacity before arriving with a large group.', null, null, null, null, null, null, null, null, null, null, null, null, array['openstreetmap']::text[], 'Điểm nhanh từ OpenStreetMap; giá là ước tính theo loại quán — kiểm lại khi đi thực địa.', null, null, null),
  ('quan-pho-ba-beo', 'approved', 'ba-vi', 'food', 'quick', 'Quán Phở Bà Béo', 'Quán Phở Bà Béo', null, 21.143088, 105.503332, 'Phố Đinh Tiên Hoàng', null, array['food']::text[], array['localFood']::text[], 30, 40, 70, null, 'butter', 'Bát phở nóng với nước dùng trong, bánh phở mềm và quẩy là lựa chọn gọn nhẹ trước một ngày di chuyển. Quán phù hợp cho bữa sáng hoặc lúc cần ăn nhanh ở khu vực Sơn Tây.', 'A hot bowl of phở with clear broth, soft noodles and fried dough is an easy start to a day on the road. It suits breakfast or a quick meal around Sơn Tây.', null, null, 'Phở dễ ăn, phục vụ nhanh và đủ ấm bụng trước khi lên các cung đường đồi núi.', 'Phở is quick, comforting and filling before heading onto the hill roads.', 'Chụp gần mặt bát khi còn bốc khói, đặt quẩy và rau thơm ở cạnh khung hình.', 'Shoot close to the bowl while it is still steaming, with fried dough and herbs at the edge of the frame.', 'Giờ bán có thể tập trung vào buổi sáng. Nên đến sớm và hỏi giá trước nếu gọi thêm thịt hoặc quẩy.', 'Service may focus on mornings. Arrive early and ask about extras such as more meat or fried dough.', null, null, null, null, null, null, null, null, null, null, null, null, array['openstreetmap']::text[], 'Điểm nhanh từ OpenStreetMap; giá là ước tính theo loại quán — kiểm lại khi đi thực địa.', null, null, null),
  ('cua-hang-bun-bay-cuong', 'approved', 'ba-vi', 'food', 'quick', 'Cửa Hàng Bún Bẩy Cường', 'Cửa Hàng Bún Bẩy Cường', null, 21.029647, 105.51737, null, null, array['food']::text[], array['localFood']::text[], 25, 35, 55, null, 'butter', 'Bún riêu có vị chua nhẹ từ cà chua, riêu cua đồng, đậu rán và rau sống. Đây là bữa ăn địa phương vừa túi tiền, hợp để đổi vị giữa hành trình.', 'Bún riêu combines a lightly tangy tomato broth with field crab, fried tofu and fresh herbs. It is an affordable local meal that adds variety to the trip.', null, null, 'Một món nước dễ ăn, có nhiều lớp vị và không quá nặng bụng khi vẫn còn phải di chuyển.', 'A flavourful noodle soup that remains light enough when there is more travelling ahead.', 'Chụp từ góc 45 độ để thấy riêu cua, đậu rán, cà chua và đĩa rau cùng lúc.', 'Shoot at a 45-degree angle to capture the crab, tofu, tomato and herb plate together.', 'Nếm nước dùng trước khi thêm mắm tôm hoặc ớt; hỏi quán nếu bạn không ăn được một nguyên liệu nào đó.', 'Taste the broth before adding shrimp paste or chilli, and tell the shop about any ingredients you cannot eat.', null, null, null, null, null, null, null, null, null, null, null, null, array['openstreetmap']::text[], 'Điểm nhanh từ OpenStreetMap; giá là ước tính theo loại quán — kiểm lại khi đi thực địa.', null, null, null),
  ('coffee-may', 'approved', 'ba-vi', 'food', 'quick', 'Cà Phê Mây', 'Cà Phê Mây', null, 21.143591, 105.502483, 'Đường Phú Hà', null, array['food','rainy']::text[], array['indoor','quiet']::text[], 30, 30, 70, null, 'butter', 'Một điểm dừng cà phê để nghỉ chân giữa các chặng tham quan Sơn Tây và Ba Vì. Có thể chọn cà phê phin, cà phê sữa hoặc đồ uống mát tùy thời tiết.', 'A coffee break between sightseeing legs around Sơn Tây and Ba Vì. Choose Vietnamese drip coffee, iced milk coffee or a cold drink to suit the weather.', null, null, 'Hữu ích khi cần nghỉ ngắn, tránh nắng hoặc chờ cả nhóm trước khi tiếp tục hành trình.', 'Useful for a short rest, shade from the heat or regrouping before the next leg.', 'Đặt ly cà phê gần cửa sổ hoặc mảng xanh; giữ hậu cảnh gọn để đồ uống nổi bật.', 'Place the coffee near a window or greenery and keep the background simple.', 'Nếu cần làm việc hoặc ngồi lâu, chọn khu vực ít ảnh hưởng đến các bàn khác và gọi thêm đồ uống khi phù hợp.', 'If staying for a while, choose a quiet seat that does not block other guests and order another drink when appropriate.', null, null, null, null, null, null, null, null, null, null, null, null, array['openstreetmap']::text[], 'Điểm nhanh từ OpenStreetMap; giá là ước tính theo loại quán — kiểm lại khi đi thực địa.', null, null, null),
  ('ben-thuy', 'approved', 'ba-vi', 'food', 'quick', 'Bến Thủy', 'Bến Thủy', null, 21.164558, 105.376123, null, null, array['food','rainy']::text[], array['indoor','quiet']::text[], 30, 30, 70, null, 'butter', 'Quán cà phê phù hợp để nghỉ giữa hành trình ở vùng Ba Vì, đặc biệt sau các chặng xe dài. Đồ uống mát và một chỗ ngồi yên giúp cả nhóm lấy lại sức.', 'A useful café break in the Ba Vì area, especially after a longer drive. A cold drink and a quiet seat give the group time to recharge.', null, null, 'Một điểm dừng linh hoạt khi lịch trình cần thêm thời gian nghỉ mà không kéo dài quá lâu.', 'A flexible stop when the itinerary needs a little more rest without taking too much time.', 'Tìm góc có ánh sáng tự nhiên và chụp đồ uống cùng khung cảnh xung quanh quán.', 'Use natural light and include a little of the café surroundings in the frame.', 'Kiểm tra giờ mở cửa trước khi đi vì quán nằm xa trung tâm và thông tin có thể thay đổi.', 'Check opening hours before setting out, as the café is outside the centre and information may change.', null, null, null, null, null, null, null, null, null, null, null, null, array['openstreetmap']::text[], 'Điểm nhanh từ OpenStreetMap; giá là ước tính theo loại quán — kiểm lại khi đi thực địa.', null, null, null),
  ('rap-2-9', 'approved', 'ba-vi', 'fun', 'quick', 'Rạp 2-9', 'Rạp 2-9', null, 21.14396, 105.505954, '9 Phố Lê Lai', null, array['fun','rainy']::text[], array['indoor','groups']::text[], 120, 70, 150, null, 'teal', 'Rạp chiếu phim ở Sơn Tây là phương án dự phòng cho buổi tối, ngày mưa hoặc khi thời tiết trên núi không thuận lợi. Có thể ghép cùng một bữa ăn gần trung tâm thị xã.', 'This Sơn Tây cinema is a backup for evenings, rainy days or poor mountain weather. It can be paired with a meal near the town centre.', null, null, 'Giúp lịch trình vẫn có hoạt động trong nhà khi các điểm ngoài trời phải rút ngắn hoặc hủy bỏ.', 'It keeps the day active when outdoor stops need to be shortened or cancelled.', 'Chụp biển tên hoặc sảnh rạp trước suất chiếu; tránh dùng máy ảnh trong phòng chiếu.', 'Photograph the sign or lobby before the screening and keep cameras off inside the auditorium.', 'Kiểm tra lịch chiếu, đến sớm lấy vé và giữ yên lặng trong phòng chiếu.', 'Check showtimes, arrive early for tickets and remain quiet during the film.', null, null, null, null, null, null, null, null, null, null, null, null, array['openstreetmap']::text[], 'Điểm nhanh từ OpenStreetMap; giá là ước tính theo loại quán — kiểm lại khi đi thực địa.', null, null, null),
  ('khu-cam-trai-son-tinh-camp', 'approved', 'ba-vi', 'fun', 'quick', 'Khu Cắm trại Sơn Tinh Camp', 'Khu Cắm trại Sơn Tinh Camp', null, 21.048652, 105.399988, null, null, array['fun','photo']::text[], array['groups','photo']::text[], 180, 50, 200, null, 'teal', 'Khu cắm trại giữa không gian xanh dưới chân Ba Vì, phù hợp cho nhóm bạn và gia đình muốn dành nhiều thời gian ngoài trời. Các hoạt động thường cần chuẩn bị trước hơn một điểm tham quan ngắn.', 'A green camping area below Ba Vì for groups and families wanting more time outdoors. It requires more planning than a short sightseeing stop.', null, null, 'Hợp với lịch trình nửa ngày hoặc qua đêm, khi mục tiêu chính là picnic, sinh hoạt nhóm và nghỉ giữa thiên nhiên.', 'Best for a half-day or overnight plan centred on picnics, group time and nature.', 'Chụp lều ở rìa khung hình, để cây và khoảng trời tạo chiều sâu; ánh sáng sớm hoặc cuối chiều đẹp hơn.', 'Place the tent near the edge of the frame and use trees and sky for depth; early and late light works best.', 'Liên hệ trước về chỗ trống, thiết bị và quy định đốt lửa. Thu gom rác và giữ yên tĩnh vào buổi tối.', 'Ask ahead about availability, equipment and fire rules. Pack out rubbish and keep noise low at night.', null, null, null, null, null, null, null, null, null, null, null, null, array['openstreetmap']::text[], 'Điểm nhanh từ OpenStreetMap; giá là ước tính theo loại quán — kiểm lại khi đi thực địa.', null, null, null),
  ('dong-mo-reservoir', 'approved', 'ba-vi', 'sight', 'quick', 'Hồ Đồng Mô', 'Hồ Đồng Mô', null, 21.05654, 105.46575, null, null, array['photo']::text[], array['photo','quiet']::text[], 45, 0, 50, null, 'leaf', 'Hồ Đồng Mô có mặt nước rộng, các doi đất xanh và tầm nhìn thoáng về vùng đồi phía tây Hà Nội. Đây là điểm dạo ngắn, ngắm hoàng hôn hoặc nghỉ giữa các điểm tham quan quanh Sơn Tây.', 'Đồng Mô offers broad water, green peninsulas and open views toward the hills west of Hanoi. It works for a short walk, sunset or a pause between Sơn Tây attractions.', null, null, 'Không gian mặt nước rộng tạo cảm giác thư thái và dễ ghép với Làng Văn hóa các Dân tộc Việt Nam gần đó.', 'The open water feels restful and pairs naturally with the nearby Vietnam National Village for Ethnic Culture and Tourism.', 'Đến cuối chiều, đặt đường bờ hoặc hàng cây ở tiền cảnh và chụp về phía mặt trời thấp.', 'Visit late in the day and use the shoreline or trees as foreground against the low sun.', 'Không xuống nước ở khu vực không được phép. Giữ sạch bờ hồ và kiểm tra lối vào vì mỗi khu ven hồ có thể có quy định riêng.', 'Do not enter the water where it is not permitted. Keep the shore clean and check access rules for each lakeside area.', null, null, null, null, null, null, null, null, null, null, null, null, array['openstreetmap']::text[], 'Điểm nhanh từ OpenStreetMap; giá là ước tính theo loại quán — kiểm lại khi đi thực địa.', null, null, null),
  ('xuan-khanh-lake', 'approved', 'ba-vi', 'sight', 'quick', 'Hồ Xuân Khanh', 'Hồ Xuân Khanh', null, 21.12682, 105.435497, null, null, array['photo']::text[], array['photo','quiet']::text[], 45, 0, 50, null, 'leaf', 'Hồ Xuân Khanh là điểm ngắm cảnh yên tĩnh giữa vùng đồi, phù hợp để dừng xe, hít thở và chụp mặt nước. Không khí ở đây nhẹ nhàng hơn các khu vui chơi đông khách.', 'Xuân Khanh Lake is a quiet scenic pause among the hills, suited to a short stop, fresh air and waterside photos. It feels calmer than the busier recreation areas.', null, null, 'Phù hợp với người muốn thêm một điểm thiên nhiên ít ồn ào vào lịch trình Ba Vì.', 'A good addition for travellers wanting a quieter nature stop on a Ba Vì itinerary.', 'Chụp mặt hồ lúc sáng sớm hoặc cuối chiều khi ánh sáng mềm và ít phản chiếu gắt.', 'Photograph early or late when the light is softer and glare on the water is lower.', 'Không xả rác, không tự ý xuống nước và tránh đi vào khu đất riêng quanh hồ.', 'Leave no litter, do not enter the water without permission and avoid private land around the lake.', null, null, null, null, null, null, null, null, null, null, null, null, array['openstreetmap']::text[], 'Điểm nhanh từ OpenStreetMap; giá là ước tính theo loại quán — kiểm lại khi đi thực địa.', null, null, null),
  ('long-pond', 'approved', 'ba-vi', 'sight', 'quick', 'Đầm Long', 'Đầm Long', null, 21.175954, 105.335392, null, null, array['photo']::text[], array['photo','quiet']::text[], 45, 0, 50, null, 'leaf', 'Đầm Long có cảnh quan hồ và nhiều mảng xanh, phù hợp cho chuyến đi gia đình hoặc nhóm muốn kết hợp ngắm cảnh với vui chơi nhẹ. Nên dành thời gian dài hơn một điểm dừng chụp ảnh thông thường.', 'Đầm Long combines a lakeside setting with extensive greenery for families or groups seeking light recreation. Allow more time than for a simple photo stop.', null, null, 'Một lựa chọn dễ tiếp cận cho nhóm có nhiều độ tuổi và không muốn đi bộ đường núi quá nhiều.', 'An accessible option for mixed-age groups that do not want a demanding mountain walk.', 'Dùng mặt hồ làm tiền cảnh, chụp rộng để lấy cả hàng cây và bầu trời.', 'Use the water as foreground and shoot wide enough to include the tree line and sky.', 'Kiểm tra giá vé và dịch vụ đang hoạt động trước khi đến; trẻ em cần có người lớn đi cùng gần mặt nước.', 'Check current tickets and operating attractions before visiting; supervise children near the water.', null, null, null, null, null, null, null, null, null, null, null, null, array['openstreetmap']::text[], 'Điểm nhanh từ OpenStreetMap; giá là ước tính theo loại quán — kiểm lại khi đi thực địa.', null, null, null),
  ('ao-vua', 'approved', 'ba-vi', 'fun', 'quick', 'Ao Vua', 'Ao Vua', null, 21.097639, 105.375386, null, null, array['fun','photo']::text[], array['groups','photo']::text[], 120, 50, 150, null, 'teal', 'Ao Vua nằm dưới chân núi Ba Vì, nổi bật với suối, thác, bóng cây và các hoạt động giải trí theo mùa. Điểm này hợp với gia đình muốn kết hợp làm mát, đi bộ nhẹ và vui chơi trong một buổi.', 'Ao Vua sits below Ba Vì mountain with streams, waterfalls, shade and seasonal recreation. It suits families combining a cool retreat, light walking and play in one outing.', null, null, 'Không khí mát và nhiều hoạt động trong cùng khu vực giúp nhóm gia đình dễ sắp xếp lịch trình.', 'Cooler surroundings and several activities in one place make planning easier for families.', 'Chụp thác với tốc độ màn trập chậm nếu thiết bị cho phép; nếu dùng điện thoại, giữ máy chắc và tránh nắng gắt giữa trưa.', 'Use a slower shutter for the waterfall if possible; on a phone, hold steady and avoid harsh midday light.', 'Đi giày chống trượt, trông trẻ gần nước và kiểm tra giá vé cùng tình trạng hoạt động trước khi đi.', 'Wear shoes with grip, supervise children near water and check current tickets and operating conditions before travelling.', null, null, null, null, null, null, null, null, null, null, null, null, array['openstreetmap']::text[], 'Điểm nhanh từ OpenStreetMap; giá là ước tính theo loại quán — kiểm lại khi đi thực địa.', null, null, null),
  ('dinh-vua', 'approved', 'ba-vi', 'sight', 'quick', 'Đỉnh Vua', 'Đỉnh Vua', null, 21.057996, 105.367347, null, null, array['photo']::text[], array['photo','iconic']::text[], 60, 0, 60, null, 'leaf', 'Đỉnh Vua cao 1.296 m, là điểm cao nhất dãy Ba Vì và nằm trong Vườn quốc gia. Đường lên có nhiều bậc đá; phía trên là không khí mát, rừng núi và tầm nhìn rộng khi trời quang.', 'At 1,296 metres, King Peak is the highest point in the Ba Vì range inside the national park. The climb has many stone steps, with cool forest air and broad views in clear weather.', null, null, 'Đây là cột mốc tiêu biểu nhất cho người muốn cảm nhận độ cao và cảnh quan của Ba Vì.', 'The signature high point for travellers wanting the full sense of Ba Vì’s elevation and landscape.', 'Ngày quang, chụp từ bậc cao nhìn xuống đồng bằng; ngày có sương, dùng hàng cây và bậc đá tạo chiều sâu.', 'On clear days shoot down toward the plain; in mist, use trees and stone steps to create depth.', 'Mang nước, áo khoác mỏng và giày bám tốt. Không rời lối đi, bẻ cây hoặc bỏ rác trong rừng.', 'Bring water, a light jacket and shoes with grip. Stay on the trail and leave plants and rubbish untouched.', null, null, null, null, null, null, null, null, null, null, null, null, array['openstreetmap']::text[], 'Điểm nhanh từ OpenStreetMap; giá là ước tính theo loại quán — kiểm lại khi đi thực địa.', null, null, null),
  ('dinh-ngoc-hoa', 'approved', 'ba-vi', 'sight', 'quick', 'Đỉnh Ngọc Hoa', 'Đỉnh Ngọc Hoa', null, 21.069448, 105.358007, null, null, array['photo']::text[], array['photo','quiet']::text[], 60, 0, 60, null, 'leaf', 'Đỉnh Ngọc Hoa cao khoảng 1.131 m, là một trong ba đỉnh chính của dãy Ba Vì. Cung đường mang vẻ yên tĩnh với rừng, sương và không khí mát hơn vùng chân núi.', 'Ngọc Hoa Peak rises to about 1,131 metres and is one of the three main summits of Ba Vì. Its route feels quiet, with forest, mist and cooler air than the foothills.', null, null, 'Phù hợp với người thích cảnh rừng và muốn một trải nghiệm ít mang tính biểu tượng nhưng tĩnh lặng hơn Đỉnh Vua.', 'A quieter forest experience for travellers who prefer calm scenery to the landmark status of King Peak.', 'Chụp đường mòn uốn giữa hàng cây; sương nhẹ buổi sáng tạo lớp cảnh đẹp nhưng cần bảo vệ thiết bị khỏi ẩm.', 'Frame the trail winding through the trees; morning mist adds depth, but protect equipment from moisture.', 'Kiểm tra điều kiện đường và thời tiết. Đi theo nhóm, mang giày phù hợp và không tự mở lối mới trong rừng.', 'Check trail and weather conditions. Walk with others, wear suitable shoes and do not create new paths through the forest.', null, null, null, null, null, null, null, null, null, null, null, null, array['openstreetmap']::text[], 'Điểm nhanh từ OpenStreetMap; giá là ước tính theo loại quán — kiểm lại khi đi thực địa.', null, null, null),
  ('french-ruins', 'approved', 'ba-vi', 'sight', 'quick', 'Phế tích Pháp', 'Phế tích Pháp', null, 21.074341, 105.364522, null, null, array['photo','history']::text[], array['photo','quiet']::text[], 30, 0, 0, null, 'leaf', 'Những bức tường gạch phủ rêu còn lại từ các công trình thời Pháp nằm lẫn trong rừng Ba Vì. Rễ cây, sương và ánh sáng lọc qua tán lá tạo nên không gian trầm, hợp với người thích lịch sử và nhiếp ảnh.', 'Moss-covered brick walls from French-era buildings sit among the Ba Vì forest. Roots, mist and filtered light create a moody place for history and photography.', null, null, 'Sự kết hợp giữa phế tích và rừng già tạo trải nghiệm khác hẳn các điểm ngắm cảnh thông thường.', 'The meeting of ruins and mature forest feels very different from an ordinary scenic viewpoint.', 'Chụp xiên qua cửa hoặc ô tường, dùng rễ cây và rêu làm tiền cảnh; trời âm u thường cho màu đẹp hơn nắng gắt.', 'Shoot through a doorway or wall opening with roots and moss in front; overcast light often works better than harsh sun.', 'Không leo lên tường, dịch chuyển gạch đá hoặc đi vào phần có nguy cơ sụp. Giữ nguyên rêu và cây bám trên di tích.', 'Do not climb walls, move bricks or enter unstable sections. Leave moss and vegetation on the ruins untouched.', null, null, null, null, null, null, null, null, null, null, null, null, array['openstreetmap']::text[], 'Điểm nhanh từ OpenStreetMap; giá là ước tính theo loại quán — kiểm lại khi đi thực địa.', null, null, null),
  ('khu-trung-bay-may-bay', 'approved', 'ba-vi', 'sight', 'quick', 'Khu trưng bày máy bay Sơn Tây', 'Khu trưng bày máy bay Sơn Tây', null, 21.140398, 105.504919, null, null, array['history','photo']::text[], array['free','photo']::text[], 20, 0, 0, null, 'teal', 'Khu trưng bày ngoài trời tại Sơn Tây có các máy bay quân sự như MiG-21 và trực thăng Mi-8. Điểm dừng ngắn này phù hợp với người quan tâm đến kỹ thuật, hàng không và lịch sử hiện đại.', 'This outdoor Sơn Tây display includes military aircraft such as a MiG-21 and Mi-8 helicopter. It is a short stop for visitors interested in engineering, aviation and modern history.', null, null, 'Có thể quan sát kích thước và cấu tạo bên ngoài của máy bay ở khoảng cách gần hơn so với chỉ xem qua ảnh.', 'It lets visitors appreciate the aircraft’s scale and exterior details more clearly than photographs can.', 'Dùng góc máy thấp để lấy trọn thân và cánh; buổi sáng hoặc cuối chiều giúp bề mặt kim loại bớt chói.', 'Use a low angle to fit the fuselage and wings; morning or late light reduces glare on metal surfaces.', 'Không trèo lên hiện vật hoặc vượt rào. Kiểm tra quyền tiếp cận và tuân thủ biển hướng dẫn tại chỗ.', 'Do not climb on exhibits or cross barriers. Check public access and follow all signs on site.', null, null, null, null, null, null, null, null, null, null, null, null, array['openstreetmap']::text[], 'Điểm nhanh từ OpenStreetMap; giá là ước tính theo loại quán — kiểm lại khi đi thực địa.', null, null, null),
  ('ba-vi-national-park', 'approved', 'ba-vi', 'sight', 'full', 'Vườn quốc gia Ba Vì', 'Vườn quốc gia Ba Vì', null, 21.018378, 105.40799, null, null, array['photo','culture']::text[], array['iconic','photo','groups']::text[], 180, 40, 80, null, 'leaf', 'Rừng, mây và ba đỉnh núi thiêng ngay cạnh Hà Nội.', 'Forest, clouds and three sacred peaks right next to Hanoi.', 'Vườn quốc gia Ba Vì được thành lập năm 1991, rộng khoảng 10.800 ha, cách trung tâm Hà Nội chừng 50 km. Dãy núi có ba đỉnh chính: đỉnh Vua cao 1.296 m, đỉnh Tản Viên 1.227 m và đỉnh Ngọc Hoa 1.131 m. Cả khối núi là một ngọn núi lửa cổ đã ngừng hoạt động từ hàng trăm triệu năm trước. Người xưa gọi đây là núi Tản và coi là núi thiêng — nơi ngự của Tản Viên Sơn Thánh, chính là Sơn Tinh trong truyền thuyết Sơn Tinh – Thủy Tinh. Rừng ở đây có hơn một nghìn loài thực vật, trong đó khoảng hai trăm loài cây thuốc.', 'Ba Vì National Park was created in 1991. It covers about 10,800 hectares, some 50 km from central Hanoi. The range has three main peaks: King Peak at 1,296 m, Tản Viên at 1,227 m and Ngọc Hoa at 1,131 m. The whole massif is an ancient volcano that went quiet hundreds of millions of years ago. People have long called it Mount Tản and treated it as sacred — the home of Tản Viên Sơn Thánh, the Mountain God of the famous legend of the Mountain God and the Water God. The forest holds more than a thousand plant species, around two hundred of them medicinal.', 'Trong một ngày từ Hà Nội, bạn đổi phố phường lấy rừng thông, mây mù và không khí mát hẳn — lại gắn với một truyền thuyết ai cũng biết.', 'In a day trip from Hanoi you swap busy streets for pine forest, mist and cool air — tied to a legend every Vietnamese child knows.', 'Đi sớm để có mây vờn quanh đỉnh; rừng thông trên đường lên là góc chụp chân dung đẹp.', 'Go early to catch clouds drifting around the peaks; the pine forest on the way up makes great portraits.', 'Không bẻ cây, hái hoa hay xả rác trong rừng. Trên núi lạnh và ẩm hơn dưới xuôi — mang áo khoác và giày bám tốt.', 'Don’t pick plants or leave litter in the forest. It is colder and damper up the mountain — bring a jacket and good shoes.', 'Đỉnh cao nhất của dãy Ba Vì tên là gì?', 'What is the highest peak of the Ba Vì range called?', 'Đỉnh Vua', 'King Peak (Đỉnh Vua)', 'Đỉnh Tản Viên', 'Tản Viên Peak', 'Đỉnh Ngọc Hoa', 'Ngọc Hoa Peak', 'Tên đỉnh là một tước hiệu cao nhất của triều đình.', 'Its name is the highest title in a royal court.', 1, 'Q1134517', array['wikipedia:vi:Vườn_quốc_gia_Ba_Vì','wikipedia:en:Ba_Vì_National_Park']::text[], 'Đã duyệt 2026-09-27. Nội dung AI viết nháp dựa trên tư liệu; giá vé là ước tính.', null, null, null),
  ('son-tay-ancient-citadel', 'approved', 'ba-vi', 'sight', 'full', 'Thành cổ Sơn Tây', 'Thành cổ Sơn Tây', null, 21.139133, 105.504492, null, null, array['history','photo']::text[], array['history','photo','free']::text[], 45, 0, 20, null, 'brick', 'Tòa thành đá ong gần 200 tuổi giữa lòng phố Sơn Tây.', 'A 200-year-old laterite fortress in the heart of Sơn Tây.', 'Năm 1822, vua Minh Mạng cho xây thành Sơn Tây để giữ vùng đất phía tây bắc kinh thành. Thành xây theo lối Vauban của phương Tây, tường bằng đá ong màu nâu đỏ, bốn cổng xây gạch, có hào nước bao quanh. Sơn Tây khi ấy là một trong bốn trấn quan trọng che chở cho Thăng Long. Những năm 1870–1880, nơi đây là căn cứ chống Pháp của quan quân nhà Nguyễn; thành thất thủ ngày 16 tháng 12 năm 1883. Năm 1994, thành được công nhận là di tích lịch sử – kiến trúc quốc gia, và là một trong số ít tòa thành thời Minh Mạng còn lại đến nay.', 'In 1822 Emperor Minh Mạng had the Sơn Tây citadel built to guard the lands north-west of the capital. It follows the Western Vauban style: reddish-brown laterite walls, four brick gates and a moat all around. Sơn Tây was then one of the four key provinces shielding Thăng Long. In the 1870s and 1880s it was a Nguyễn stronghold against the French, and it fell on 16 December 1883. It was listed as a national historic site in 1994 and is one of the few Minh Mạng-era citadels still standing.', 'Đá ong là “chữ ký” của xứ Đoài — ở đây bạn thấy cả một tòa thành làm từ nó, vẫn còn nguyên hào nước và cổng cổ.', 'Laterite is the signature stone of this region — here a whole fortress is built from it, moat and old gates still in place.', 'Chụp cổng thành từ bên kia hào nước, lúc nắng chiều làm đá ong đỏ lên.', 'Shoot a gate from across the moat in late-afternoon light, when the laterite glows red.', 'Không leo trèo lên tường thành và cổng cổ.', 'Please don’t climb the walls or the old gates.', 'Tường thành Sơn Tây được xây chủ yếu bằng vật liệu gì?', 'What is the Sơn Tây citadel wall mainly built from?', 'Đá ong', 'Laterite stone', 'Gạch men', 'Glazed tiles', 'Bê tông', 'Concrete', 'Đá màu nâu đỏ, bề mặt lỗ chỗ như tổ ong.', 'A reddish stone full of little holes, like a honeycomb.', 1, 'Q4240280', array['wikipedia:vi:Thành_cổ_Sơn_Tây']::text[], 'Đã duyệt 2026-09-27. Nội dung AI viết nháp dựa trên tư liệu; giá vé là ước tính.', null, null, null),
  ('ho-suoi-hai', 'approved', 'ba-vi', 'sight', 'full', 'Hồ Suối Hai', 'Hồ Suối Hai', null, 21.146783, 105.39091, null, null, array['photo']::text[], array['photo','quiet']::text[], 60, 0, 50, null, 'teal', 'Mặt hồ rộng in bóng núi Tản, lấm tấm đảo nhỏ.', 'A wide lake mirroring Mount Tản, dotted with small islands.', 'Hồ Suối Hai là hồ nhân tạo, khởi công cuối năm 1958 và khánh thành năm 1964. Hồ chứa khoảng 46,8 triệu mét khối nước, dẫn nước tưới cho hơn 7.000 ha ruộng đồng quanh vùng. Lòng hồ có 14 hòn đảo lớn nhỏ, phía xa là dãy núi Tản. Từ một công trình thủy lợi, Suối Hai dần thành điểm dã ngoại quen thuộc của người Hà Nội.', 'Suối Hai is a man-made lake: work began at the end of 1958 and it opened in 1964. It holds about 46.8 million cubic metres of water and irrigates more than 7,000 hectares of farmland. Fourteen islands dot the water, with the Tản mountains behind. Built for farming, it has become a favourite picnic spot for Hanoians.', 'Một hồ “làm ruộng” mà đẹp như tranh — nơi hiếm hoi gần Hà Nội có mặt nước rộng và núi làm nền.', 'A lake built for rice fields that looks like a painting — one of the few places near Hanoi with wide water and mountains behind it.', 'Chiều muộn đứng trên bờ đê nhìn về phía núi — mặt hồ phẳng sẽ phản chiếu dãy Tản.', 'Late afternoon, stand on the dam looking toward the mountains — the calm water mirrors the range.', 'Hồ là nguồn nước tưới: không xả rác, không tắm ở chỗ có biển cấm.', 'The lake waters the fields: no litter, and no swimming where signs forbid it.', 'Hồ Suối Hai được xây dựng chủ yếu để làm gì?', 'What was Suối Hai lake mainly built for?', 'Dẫn nước tưới ruộng', 'Irrigating farmland', 'Làm bể bơi cho khách du lịch', 'A swimming pool for tourists', 'Nuôi cá cảnh', 'Breeding ornamental fish', 'Nó giúp hơn 7.000 ha đồng ruộng có nước.', 'It keeps more than 7,000 hectares of fields watered.', 1, 'Q10771991', array['wikipedia:vi:Hồ_Suối_Hai']::text[], 'Đã duyệt 2026-09-27. Nội dung AI viết nháp dựa trên tư liệu; giá vé là ước tính.', null, null, null),
  ('village-for-ethnic-culture-and-tourism', 'approved', 'ba-vi', 'sight', 'full', 'Làng Văn hóa - Du lịch các Dân tộc Việt Nam', 'Làng Văn hóa - Du lịch các Dân tộc Việt Nam', null, 21.041548, 105.463239, null, null, array['culture','photo']::text[], array['cultural','groups','photo']::text[], 120, 0, 100, null, 'brick', 'Nhà cửa, trang phục và lễ hội của các dân tộc Việt Nam ở một nơi.', 'Houses, dress and festivals of Vietnam’s ethnic groups in one place.', 'Làng nằm cạnh hồ Đồng Mô, được xây dựng để giới thiệu văn hóa của 54 dân tộc Việt Nam. Mỗi khu làng dựng lại kiểu nhà truyền thống — nhà sàn, nhà rông, nhà trình tường… — và thường có đồng bào các dân tộc về sinh sống, biểu diễn, tổ chức lễ hội. Chỉ một buổi, bạn có thể đi qua kiến trúc và phong tục của nhiều vùng từ núi cao phía Bắc đến Tây Nguyên.', 'The village sits beside Đồng Mô lake and was built to present the cultures of Vietnam’s 54 ethnic groups. Each hamlet rebuilds a traditional house type — stilt houses, communal rông houses, rammed-earth homes — and people from the communities often live, perform and hold festivals there. In one afternoon you walk through the architecture and customs of regions from the northern mountains to the Central Highlands.', 'Cách dễ nhất để thấy Việt Nam không chỉ có người Kinh — rất hợp cho gia đình có trẻ em.', 'The easiest way to see that Vietnam is far more than one culture — great for families with kids.', 'Nhà rông với mái cao vút là góc chụp ấn tượng nhất; xin phép trước khi chụp người.', 'The tall-roofed rông house is the most striking shot; ask before photographing people.', 'Xin phép trước khi vào nhà hoặc chụp ảnh người dân; không chạm vào đồ thờ.', 'Ask before entering a house or photographing people; don’t touch altars or ritual objects.', 'Việt Nam có bao nhiêu dân tộc?', 'How many ethnic groups does Vietnam officially have?', '54', '54', '64', '64', '45', '45', 'Một số chẵn, lớn hơn 50 một chút.', 'An even number, just over 50.', 1, null, array['kiến thức chung — cần đối chiếu']::text[], 'Đã duyệt 2026-09-27. Nội dung AI viết nháp dựa trên tư liệu; giá vé là ước tính.', null, null, null),
  ('dinh-mong-phu', 'approved', 'ba-vi', 'sight', 'full', 'Đình Mông Phụ (làng cổ Đường Lâm)', 'Đình Mông Phụ (làng cổ Đường Lâm)', null, 21.158467, 105.470445, null, null, array['culture','history','photo']::text[], array['cultural','history','photo']::text[], 30, 0, 20, null, 'brick', 'Ngôi đình gần 500 tuổi ở trái tim làng cổ Đường Lâm.', 'A nearly 500-year-old communal house at the heart of Đường Lâm village.', 'Đình Mông Phụ nằm trên khu đất cao nhất, ở trung tâm làng cổ Đường Lâm. Đình được dựng năm 1533 thời vua Mạc Đăng Doanh, sửa lần đầu năm 1858 và đại tu năm 2006–2008, nhưng vẫn giữ kiến trúc và điêu khắc từ đầu thế kỷ 19. Đình thờ Tản Viên Sơn Thánh. Hai bên đình có hai giếng cổ mà dân làng gọi là “hai mắt rồng”. Mái đình võng nhẹ, góc mái cong vút thành hình rồng; các đầu xà chạm rồng, hổ, cá, chim, mây.', 'Mông Phụ communal house stands on the highest ground at the centre of Đường Lâm’s old village. It was built in 1533 under King Mạc Đăng Doanh, first repaired in 1858 and restored in 2006–2008, yet it keeps its early-19th-century structure and carvings. It honours Tản Viên Sơn Thánh, the mountain god of Ba Vì. Two old wells flank it — villagers call them the “dragon’s eyes”. The roof sags gently and its corners curl up into dragons; beams are carved with dragons, tigers, fish, birds and clouds.', 'Đình làng là “trụ sở” của làng Việt xưa — nơi họp, nơi lễ hội. Ở Đường Lâm, bạn thấy nó giữa những ngôi nhà đá ong vẫn có người ở.', 'The communal house was the town hall of the old Vietnamese village — meetings and festivals. In Đường Lâm it still stands among laterite houses people live in.', 'Chụp từ sân đình về phía nghi môn, hoặc đi dạo các ngõ tường đá ong quanh đình.', 'Shoot from the courtyard toward the gate, or wander the laterite-walled lanes around it.', 'Đây là nơi thờ tự và làng có người ở: ăn mặc kín đáo, nói nhỏ, không chụp ảnh vào nhà dân khi chưa xin phép.', 'A place of worship in a lived-in village: dress modestly, keep your voice low, don’t photograph into homes without asking.', 'Dân làng gọi hai giếng cổ hai bên đình Mông Phụ là gì?', 'What do villagers call the two old wells beside Mông Phụ?', 'Hai mắt rồng', 'The dragon’s eyes', 'Hai giếng tiên', 'The fairy wells', 'Giếng vua', 'The king’s wells', 'Con vật được chạm khắp mái đình.', 'The creature carved all over the roof.', 1, 'Q16481108', array['wikipedia:vi:Đình_Mông_Phụ']::text[], 'Đã duyệt 2026-09-27. Nội dung AI viết nháp dựa trên tư liệu; giá vé là ước tính.', null, null, null),
  ('den-thuong', 'approved', 'ba-vi', 'sight', 'full', 'Đền Thượng', 'Đền Thượng', null, 21.062117, 105.361165, null, null, array['culture','photo']::text[], array['cultural','photo']::text[], 45, 0, 0, null, 'brick', 'Ngôi đền thờ Sơn Tinh gần đỉnh Tản Viên, giữa mây.', 'A temple to the Mountain God near Tản Viên peak, up in the clouds.', 'Đền Thượng nằm gần đỉnh Tản Viên, thờ Tản Viên Sơn Thánh — tức Sơn Tinh. Theo truyền thuyết, Sơn Tinh và Thủy Tinh cùng cầu hôn Mị Nương, con gái vua Hùng thứ mười tám. Sơn Tinh mang sính lễ đến trước nên cưới được nàng; Thủy Tinh tức giận dâng nước đánh, Sơn Tinh bốc đồi dời núi chặn lại. Người Việt kể chuyện ấy để giải thích lũ lụt hằng năm. Tản Viên Sơn Thánh là một trong “tứ bất tử” — bốn vị thánh bất tử trong tín ngưỡng dân gian Việt Nam.', 'Đền Thượng (the Upper Temple) stands near Tản Viên peak and honours Tản Viên Sơn Thánh — Sơn Tinh, the Mountain God. In the legend, the Mountain God and the Water God both asked for the hand of Mị Nương, daughter of the 18th Hùng King. The Mountain God brought his wedding gifts first and won her; the furious Water God raised floods, and the Mountain God lifted hills to hold them back. Vietnamese people tell this story to explain the yearly floods. The Mountain God is one of the “Four Immortals” of Vietnamese folk belief.', 'Bạn đang đứng ở nơi người Việt tin là nhà của Sơn Tinh — nhân vật trong câu chuyện cổ tích đầu tiên mà hầu hết trẻ em Việt Nam được nghe.', 'You are standing where Vietnamese people believe the Mountain God lives — the hero of one of the first folk tales every child here hears.', 'Ngày có mây, chụp mái đền nhô lên giữa sương; ngày quang, chụp từ bậc đá nhìn xuống thung lũng.', 'On cloudy days, frame the roof rising out of the mist; on clear days, shoot down the valley from the stone steps.', 'Nơi thờ tự linh thiêng: ăn mặc kín đáo, không đùa nghịch, không chụp ảnh bàn thờ nếu có biển cấm. Đường lên nhiều bậc dốc.', 'A sacred place: dress modestly, stay respectful, and don’t photograph altars where signs say not to. The way up has many steep steps.', 'Theo truyền thuyết, Sơn Tinh cưới được ai?', 'In the legend, whom did the Mountain God marry?', 'Mị Nương, con gái vua Hùng', 'Mị Nương, daughter of the Hùng King', 'Âu Cơ', 'Âu Cơ', 'Tiên Dung', 'Tiên Dung', 'Cha của nàng là vị vua Hùng thứ mười tám.', 'Her father was the 18th Hùng King.', 1, null, array['kiến thức chung — cần đối chiếu (vị trí theo OpenStreetMap)']::text[], 'Đã duyệt 2026-09-27. Nội dung AI viết nháp dựa trên tư liệu; giá vé là ước tính.', null, null, null),
  ('tan-da-nguyen-khac-hieu-memorial-site', 'approved', 'ba-vi', 'sight', 'full', 'Di tích lưu niệm Tản Đà - Nguyễn Khắc Hiếu', 'Di tích lưu niệm Tản Đà - Nguyễn Khắc Hiếu', null, 21.185351, 105.30767, null, null, array['culture','history']::text[], array['cultural','quiet','history']::text[], 30, 0, 0, null, 'brick', 'Quê hương của nhà thơ lấy tên núi Tản, sông Đà làm bút danh.', 'Home village of the poet who took his pen name from Mount Tản and the Đà river.', 'Tản Đà (1889–1939), tên thật Nguyễn Khắc Hiếu, là nhà thơ nổi tiếng đầu thế kỷ 20, sinh ra ở vùng đất này. Bút danh của ông ghép từ núi Tản (Ba Vì) và sông Đà — hai hình ảnh quê hương mà ông mang theo cả đời. Thơ Tản Đà phóng khoáng, lãng mạn, được xem là gạch nối giữa thơ cổ điển và Thơ mới. Khu lưu niệm giữ lại không gian quê nhà và tư liệu về cuộc đời ông.', 'Tản Đà (1889–1939), born Nguyễn Khắc Hiếu, was a celebrated early-20th-century poet from this area. His pen name joins Mount Tản (Ba Vì) and the Đà river — two images of home he carried all his life. His free-spirited, romantic poetry is seen as the bridge between classical verse and the “New Poetry” movement. The memorial keeps his home village setting and records of his life.', 'Hiếm có nhà thơ nào gắn tên mình với phong cảnh quê hương rõ đến thế — đứng đây, bạn thấy cả núi lẫn sông trong bút danh ấy.', 'Few poets tie their very name to their landscape so clearly — from here you can see both the mountain and the river in it.', 'Chụp khung cảnh làng quê với núi Tản phía xa làm nền.', 'Frame the village with Mount Tản in the background.', 'Nơi lưu niệm yên tĩnh: nói nhỏ, không chạm vào hiện vật.', 'A quiet memorial: keep your voice down and don’t touch the exhibits.', 'Bút danh “Tản Đà” ghép từ tên của những gì?', 'What does the pen name “Tản Đà” combine?', 'Núi Tản và sông Đà', 'Mount Tản and the Đà river', 'Tên hai người thầy', 'The names of two teachers', 'Tên hai ngôi làng', 'The names of two villages', 'Nhìn quanh: một ngọn núi và một con sông.', 'Look around: a mountain and a river.', 1, null, array['kiến thức chung — cần đối chiếu']::text[], 'Đã duyệt 2026-09-27. Nội dung AI viết nháp dựa trên tư liệu; giá vé là ước tính.', null, null, null),
  ('den-va', 'approved', 'ba-vi', 'sight', 'full', 'Đền Và', 'Đền Và', null, 21.138634, 105.485423, null, null, array['culture','photo']::text[], array['cultural','quiet','photo']::text[], 30, 0, 0, null, 'brick', 'Đền thờ Sơn Tinh giữa rừng lim cổ thụ ở Sơn Tây.', 'A temple to the Mountain God in a grove of ancient ironwood trees.', 'Đền Và ở Sơn Tây thờ Tản Viên Sơn Thánh, vị thần núi Ba Vì. Đền nằm trên một quả đồi thấp, bao quanh là rừng lim cổ thụ tỏa bóng mát. Kiến trúc đền theo lối cổ với nghi môn, sân và các lớp nhà thờ, mái ngói phủ rêu. Với người xứ Đoài, đây là một trong những nơi thờ Sơn Tinh quan trọng nhất ở vùng đồng bằng dưới chân núi.', 'Đền Và in Sơn Tây honours Tản Viên Sơn Thánh, the god of Ba Vì mountain. It sits on a low hill surrounded by ancient ironwood (lim) trees that give deep shade. The temple follows the old layout — ceremonial gate, courtyard, halls one behind another — under moss-covered tiled roofs. For the people of this region it is one of the most important Mountain God temples on the plain below the mountain.', 'Nếu không lên được núi, đây là nơi dễ đến để “gặp” Sơn Tinh — và rừng lim quanh đền rất hiếm thấy ở đồng bằng.', 'If you can’t climb the mountain, this is the easy place to “meet” the Mountain God — and an ironwood grove like this is rare on the plain.', 'Chụp lối vào đền xuyên qua hàng lim, lúc nắng xiên buổi sáng.', 'Shoot the path into the temple through the ironwood trees in slanting morning light.', 'Nơi thờ tự: ăn mặc kín đáo, không đùa nghịch, không bẻ cành lim.', 'A place of worship: dress modestly, be respectful and don’t break branches off the old trees.', 'Đền Và thờ vị thần nào?', 'Which god is honoured at Đền Và?', 'Tản Viên Sơn Thánh (Sơn Tinh)', 'Tản Viên Sơn Thánh (the Mountain God)', 'Thủy Tinh', 'The Water God', 'Thánh Gióng', 'Saint Gióng', 'Vị thần của ngọn núi nhìn thấy từ đây.', 'The god of the mountain you can see from here.', 1, null, array['kiến thức chung — cần đối chiếu']::text[], 'Đã duyệt 2026-09-27. Nội dung AI viết nháp dựa trên tư liệu; giá vé là ước tính.', null, null, null),
  ('lang-ngo-quyen', 'approved', 'ba-vi', 'sight', 'full', 'Lăng Ngô Quyền', 'Lăng Ngô Quyền', null, 21.147143, 105.462492, null, null, array['history','culture']::text[], array['history','quiet']::text[], 20, 0, 0, null, 'brick', 'Nơi tưởng niệm vị vua mở đầu nền độc lập, ở quê hương Đường Lâm.', 'A memorial to the king who began Vietnam’s independence, in his home village of Đường Lâm.', 'Ngô Quyền sinh ra ở Đường Lâm. Năm 938, ông đánh tan quân Nam Hán trên sông Bạch Đằng: cho cắm cọc gỗ đầu bịt sắt dưới lòng sông, nhử thuyền giặc vào lúc nước lên, rồi phản công khi nước rút để cọc đâm thủng thuyền. Năm 939 ông xưng vương, chấm dứt hơn một nghìn năm Bắc thuộc. Đường Lâm vì thế được gọi là “đất hai vua” — quê của Ngô Quyền và Bố Cái Đại Vương Phùng Hưng.', 'Ngô Quyền was born in Đường Lâm. In 938 he destroyed the Southern Han fleet on the Bạch Đằng river: he had iron-tipped wooden stakes planted in the riverbed, lured the enemy ships in at high tide, then attacked as the tide fell so the stakes tore their hulls. In 939 he declared himself king, ending more than a thousand years of Chinese rule. That is why Đường Lâm is called the “land of two kings” — home of Ngô Quyền and of Phùng Hưng.', 'Trận Bạch Đằng là một trong những chiến thắng nổi tiếng nhất lịch sử Việt Nam — và người chỉ huy nó sinh ra ngay tại làng này.', 'The battle of Bạch Đằng is one of the most famous victories in Vietnamese history — and the man who led it was born in this very village.', 'Chụp tấm bia và cổng lăng từ phía trước, giữ khung hình cân đối, trang nghiêm.', 'Photograph the stele and gate straight on — keep the frame symmetrical and dignified.', 'Nơi tưởng niệm: giữ yên lặng, ăn mặc lịch sự, không ngồi lên bia hay tường.', 'A memorial: stay quiet, dress respectfully and don’t sit on the steles or walls.', 'Ở trận Bạch Đằng năm 938, Ngô Quyền dùng cách gì để phá thuyền giặc?', 'How did Ngô Quyền wreck the enemy fleet at Bạch Đằng in 938?', 'Cắm cọc gỗ đầu bịt sắt dưới lòng sông', 'Iron-tipped stakes planted in the riverbed', 'Đắp đê chặn dòng sông', 'Damming the river', 'Dùng voi chiến lội sông', 'War elephants wading into the river', 'Thủy triều rút chính là “vũ khí”.', 'The falling tide was the real weapon.', 1, null, array['kiến thức chung — cần đối chiếu']::text[], 'Đã duyệt 2026-09-27. Nội dung AI viết nháp dựa trên tư liệu; giá vé là ước tính.', null, null, null),
  ('chua-mia', 'approved', 'ba-vi', 'sight', 'full', 'Chùa Mía', 'Chùa Mía', null, 21.161904, 105.467315, null, null, array['culture','history','photo']::text[], array['cultural','quiet','photo']::text[], 30, 0, 0, null, 'brick', 'Ngôi chùa có hàng trăm pho tượng cổ ở làng Đường Lâm.', 'A village pagoda holding hundreds of old statues, in Đường Lâm.', 'Chùa Mía, tên chữ là Sùng Nghiêm tự, nằm trong làng cổ Đường Lâm. Chùa gắn với bà chúa Mía — một phi tần của chúa Trịnh, người quê ở đây — đã bỏ tiền xây dựng lại chùa vào thế kỷ 17. Điều làm chùa nổi tiếng là số tượng rất lớn, gần ba trăm pho, bằng gỗ và đất nung, nhiều pho có niên đại vài trăm năm. Đi trong chùa giống như đi qua một bảo tàng điêu khắc dân gian.', 'Chùa Mía, formally Sùng Nghiêm Pagoda, stands in Đường Lâm’s old village. It is linked to Lady Mía — a consort of the Trịnh lords who came from here — who paid to rebuild it in the 17th century. What makes it famous is its huge number of statues, close to three hundred, in wood and clay, many of them several centuries old. Walking through it feels like walking through a museum of folk sculpture.', 'Ít ngôi chùa làng nào có nhiều tượng cổ như vậy — mỗi pho một nét mặt, một tư thế.', 'Few village pagodas have so many old statues — each with its own face and pose.', 'Trong chùa tối — tắt đèn flash, chụp tượng với ánh sáng tự nhiên từ cửa.', 'It’s dim inside — turn off the flash and shoot the statues in the natural light from the doors.', 'Nơi thờ Phật: ăn mặc kín đáo, bỏ mũ, nói nhỏ; xin phép trước khi chụp ảnh trong điện.', 'A Buddhist place of worship: dress modestly, remove your hat, speak softly and ask before photographing inside the halls.', 'Chùa Mía nổi tiếng nhất vì điều gì?', 'What is Chùa Mía most famous for?', 'Có rất nhiều pho tượng cổ', 'Its very large number of old statues', 'Là ngôi chùa cao nhất Việt Nam', 'Being the tallest pagoda in Vietnam', 'Được xây giữa hồ', 'Being built in the middle of a lake', 'Hãy thử đếm những gì đứng trên các bệ thờ.', 'Try counting what stands on the altars.', 1, null, array['kiến thức chung — cần đối chiếu']::text[], 'Đã duyệt 2026-09-27. Nội dung AI viết nháp dựa trên tư liệu; giá vé là ước tính.', null, null, null),
  ('bao-tang-ha-noi', 'approved', 'hoan-kiem', 'sight', 'quick', 'Bảo tàng Hà Nội', 'Hanoi Museum', null, 21.01001, 105.78631, 'Phạm Hùng, Nam Từ Liêm', null, array['history','culture','rainy']::text[], array['indoor','history','photo']::text[], 75, 30, 30, null, 'teal', 'Bảo tàng về lịch sử nghìn năm Thăng Long – Hà Nội, lưu giữ hơn 70.000 tài liệu, hiện vật; toà nhà hình kim tự tháp ngược là điểm check-in quen thuộc.', 'A museum of a thousand years of Thang Long – Hanoi, holding over 70,000 documents and objects; its upside-down pyramid building is a favourite photo stop.', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, array['https://kinhte.congthuong.vn/apicenter@/print_article&i=368066']::text[], 'Nhập từ Văn hoá–Giải trí HN (tổng hợp 03/10/2026). Giá 30.000đ theo Nghị quyết 44/2024/NQ-HĐND (từ 1/1/2025); miễn phí ngày 18/5. Giờ mở cửa: xem nguồn. Bản tiếng Anh do AI dịch.', null, null, null),
  ('bao-tang-dan-toc-hoc', 'approved', 'hoan-kiem', 'sight', 'quick', 'Bảo tàng Dân tộc học Việt Nam', 'Vietnam Museum of Ethnology', null, 21.04008, 105.79884, 'Nguyễn Văn Huyên, Cầu Giấy', 'Tu-Su 08:30-17:30', array['culture','history','photo']::text[], array['cultural','groups','photo']::text[], 120, 40, 40, null, 'leaf', 'Mở cửa năm 1997, giới thiệu văn hoá 54 dân tộc Việt Nam; có khu trưng bày trong nhà, vườn nhà truyền thống ngoài trời và toà Cánh Diều về Đông Nam Á. Có biểu diễn miễn phí 2 lần/ngày ở khu vườn.', 'Opened in 1997, it presents the cultures of Vietnam’s 54 ethnic groups: indoor galleries, a garden of traditional houses and the Kite building on Southeast Asia. Free shows twice a day in the garden.', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, array['https://www.vme.org.vn','https://en.wikipedia.org/wiki/Vietnam_Museum_of_Ethnology']::text[], 'Nhập từ Văn hoá–Giải trí HN (tổng hợp 03/10/2026). Bản tiếng Anh do AI dịch.', null, null, null),
  ('bao-tang-my-thuat', 'approved', 'hoan-kiem', 'sight', 'quick', 'Bảo tàng Mỹ thuật Việt Nam', 'Vietnam National Fine Arts Museum', null, 21.03064, 105.83704, '66 Nguyễn Thái Học, Ba Đình', 'Tu-Su 08:30-17:00', array['culture','rainy','photo']::text[], array['indoor','cultural']::text[], 75, 30, 30, null, 'brick', 'Bảo tàng mỹ thuật quốc gia, nằm đối diện Văn Miếu và cách Hoàng thành khoảng 10 phút đi bộ; tiện ghép lịch tham quan cả cụm.', 'The national fine arts museum, opposite the Temple of Literature and about 10 minutes’ walk from the Imperial Citadel — easy to combine in one outing.', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, array['https://vietnam.travel/vi/things-to-do/vietnams-must-see-museums']::text[], 'Nhập từ Văn hoá–Giải trí HN (tổng hợp 03/10/2026). Bản tiếng Anh do AI dịch.', null, null, null),
  ('bao-tang-ho-chi-minh', 'draft', 'hoan-kiem', 'sight', 'quick', 'Bảo tàng Hồ Chí Minh', 'Ho Chi Minh Museum', null, 21.03562, 105.83263, '19 Ngọc Hà, Ba Đình', null, array['history','rainy']::text[], array['indoor','history']::text[], 60, 0, 40, null, 'teal', 'Trưng bày theo hành trình cuộc đời Chủ tịch Hồ Chí Minh; không gian trưng bày chính do sinh viên ĐH Mỹ thuật Hà Nội thiết kế.', 'Exhibits follow the life of President Ho Chi Minh; the main exhibition space was designed by students of the Hanoi University of Fine Arts.', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, array['https://vinwonders.com/vi/wonderpedia/news/bao-tang-binh-chung-thong-tin/','https://vietnam.travel/vi/things-to-do/vietnams-must-see-museums']::text[], 'Nhập từ Văn hoá–Giải trí HN (tổng hợp 03/10/2026). Chủ đề lãnh tụ — duyệt kỹ trước khi đưa lên (xem README). Nguồn ghi giá khách nước ngoài 40.000đ. Bản tiếng Anh do AI dịch.', null, null, null),
  ('bao-tang-thien-nhien', 'approved', 'hoan-kiem', 'sight', 'quick', 'Bảo tàng Thiên nhiên Việt Nam', 'Vietnam Museum of Nature', null, 21.04807, 105.80054, '18 Hoàng Quốc Việt, Cầu Giấy', '08:00-17:00', array['culture','rainy']::text[], array['indoor','free','groups']::text[], 60, 0, 0, null, 'leaf', 'Bảo tàng về thế giới tự nhiên Việt Nam, thường được gợi ý cho gia đình có trẻ nhỏ.', 'A museum of Vietnam’s natural world, often recommended for families with young children.', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, array['https://vinwonders.com/vi/wonderpedia/news/bao-tang-binh-chung-thong-tin/','https://vinwonders.com/vi/wonderpedia/news/bao-tang-o-ha-noi/']::text[], 'Nhập từ Văn hoá–Giải trí HN (tổng hợp 03/10/2026). Bản tiếng Anh do AI dịch.', null, null, null),
  ('bao-tang-phong-khong-khong-quan', 'draft', 'hoan-kiem', 'sight', 'quick', 'Bảo tàng Phòng không – Không quân', 'Air Defence – Air Force Museum', null, 20.99954, 105.82924, '171 Trường Chinh, Đống Đa', '08:00-11:30,13:00-16:30', array['history','photo']::text[], array['history','free','photo']::text[], 60, 0, 0, null, 'teal', 'Bảo tàng quân sự về lực lượng phòng không – không quân, có khu trưng bày khí tài ngoài trời; vào cửa miễn phí.', 'A military museum of Vietnam’s air defence and air force, with aircraft and equipment displayed outdoors; free entry.', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, array['https://vinwonders.com/vi/wonderpedia/news/bao-tang-binh-chung-thong-tin/']::text[], 'Nhập từ Văn hoá–Giải trí HN (tổng hợp 03/10/2026). Chủ đề chiến tranh — duyệt kỹ (xem README). Bản tiếng Anh do AI dịch.', null, null, null),
  ('bao-tang-binh-chung-thong-tin', 'draft', 'hoan-kiem', 'sight', 'quick', 'Bảo tàng Binh chủng Thông tin', 'Signal Corps Museum', null, 21.03034, 105.82663, '1 Giang Văn Minh, Ba Đình', null, array['history','rainy']::text[], array['indoor','history']::text[], 45, 0, 30, null, 'teal', 'Bảo tàng quân sự về lịch sử ngành thông tin liên lạc trong quân đội, trực thuộc Cục Chính trị.', 'A military museum on the history of army communications.', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, array['https://vinwonders.com/vi/wonderpedia/news/bao-tang-binh-chung-thong-tin/','https://vinpearl.com/vi/danh-sach-20-bao-tang-o-ha-noi-noi-tieng-thu-hut-du-khach']::text[], 'Nhập từ Văn hoá–Giải trí HN (tổng hợp 03/10/2026). Chủ đề quân sự — duyệt kỹ. Giá là ước tính (nguồn không ghi) — kiểm tra trước khi đi. Bản tiếng Anh do AI dịch.', null, null, null),
  ('bat-trang-tinh-hoa-lang-nghe', 'approved', 'hoan-kiem', 'sight', 'quick', 'Bảo tàng Gốm Bát Tràng (Trung tâm Tinh hoa Làng nghề Việt)', 'Bat Trang Ceramics Museum', null, 20.97388, 105.91295, 'Số 28, thôn 5, Bát Tràng, Gia Lâm', '08:00-17:00', array['culture','photo','rainy']::text[], array['cultural','indoor','photo','groups']::text[], 120, 30, 30, null, 'butter', 'Công trình kiến trúc độc đáo giữa làng gốm Bát Tràng, vừa trưng bày gốm vừa có khu trải nghiệm làm gốm (tầng G).', 'A striking building in the heart of Bat Trang pottery village, with ceramics galleries and a hands-on pottery area on the ground floor.', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, array['https://vinwonders.com/vi/wonderpedia/news/bao-tang-binh-chung-thong-tin/','https://vinwonders.com/vi/wonderpedia/news/bao-tang-o-ha-noi/','https://vinwonders.com/vi/wonderpedia/news/workshop-lam-gom-ha-noi/']::text[], 'Nhập từ Văn hoá–Giải trí HN (tổng hợp 03/10/2026). Toạ độ gần đúng (theo tên đường) — kiểm tra lại. Giá 30.000đ là vé bảo tàng; workshop làm gốm tính riêng. Bản tiếng Anh do AI dịch.', 'Nên liên hệ trước khi đến — lịch lớp có thể thay đổi.', 'Contact them before you go — class times can change.', null),
  ('bao-tang-lich-su-quan-su', 'draft', 'hoan-kiem', 'sight', 'quick', 'Bảo tàng Lịch sử Quân sự Việt Nam', 'Vietnam Military History Museum', null, 21.01159, 105.75471, 'Km 6+500 Đại lộ Thăng Long, Nam Từ Liêm', '08:00-16:30', array['history','photo']::text[], array['history','photo','groups']::text[], 90, 40, 40, null, 'teal', 'Bảo tàng quân sự quy mô lớn mới xây trên Đại lộ Thăng Long, trưng bày nhiều khí tài, hiện vật chiến tranh.', 'A large, newly built military museum on Thang Long Avenue, displaying wartime equipment and artefacts.', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{}'::text[], 'Nhập từ Văn hoá–Giải trí HN (tổng hợp 03/10/2026). Nguồn: "hiểu biết chung", chưa có link — cần bổ sung nguồn. Chủ đề chiến tranh — duyệt kỹ. Bản tiếng Anh do AI dịch.', null, null, null),
  ('bao-tang-chien-thang-b52', 'draft', 'hoan-kiem', 'sight', 'quick', 'Bảo tàng Chiến thắng B52', 'B52 Victory Museum', null, 21.03535, 105.81952, '157 Đội Cấn, Ba Đình', null, array['history']::text[], array['history','free']::text[], 45, 0, 0, null, 'teal', 'Trưng bày về chiến dịch phòng không "Hà Nội – Điện Biên Phủ trên không" tháng 12/1972, có xác máy bay B52.', 'Exhibits on the December 1972 air-defence campaign over Hanoi, including the wreck of a B-52.', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '{}'::text[], 'Nhập từ Văn hoá–Giải trí HN (tổng hợp 03/10/2026). Sheet ghi "tạm thời đóng cửa". Nguồn: "hiểu biết chung", chưa có link. Toạ độ theo tên phố. Chủ đề chiến tranh — duyệt kỹ. Bản tiếng Anh do AI dịch.', null, null, null),
  ('van-mieu', 'approved', 'hoan-kiem', 'sight', 'quick', 'Văn Miếu – Quốc Tử Giám', 'Temple of Literature', null, 21.02746, 105.835, 'Phố Quốc Tử Giám, Đống Đa', null, array['culture','history','photo']::text[], array['iconic','history','cultural','photo','groups']::text[], 75, 30, 70, null, 'brick', 'Văn Miếu thờ Khổng Tử dựng năm 1070, Quốc Tử Giám lập năm 1076, được xem là trường đại học đầu tiên của Việt Nam; nổi tiếng với Khuê Văn Các và 82 bia Tiến sĩ (Di sản tư liệu thế giới).', 'The Temple of Literature, built for Confucius in 1070, and the Imperial Academy founded in 1076 — seen as Vietnam’s first university; famous for the Khue Van pavilion and 82 doctoral stelae (UNESCO Memory of the World).', null, null, null, null, null, null, 'Ăn mặc kín đáo, nói khẽ, không chụp ảnh người đang lễ.', 'Dress modestly, keep your voice down and don’t photograph people praying.', null, null, null, null, null, null, null, null, null, null, null, null, array['https://baovanhoa.vn/di-san/trien-lam-di-tich-quoc-gia-dac-biet-o-ha-noi-59651.html','https://en.wikipedia.org/wiki/Temple_of_Literature,_Hanoi']::text[], 'Nhập từ Văn hoá–Giải trí HN (tổng hợp 03/10/2026). Giá là ước tính (nguồn không ghi) — kiểm tra trước khi đi. Toạ độ theo phố Quốc Tử Giám (cổng chính). Bản tiếng Anh do AI dịch.', null, null, null),
  ('co-loa', 'approved', 'hoan-kiem', 'sight', 'quick', 'Khu di tích Cổ Loa', 'Co Loa Citadel', null, 21.11568, 105.86844, 'Cổ Loa, Đông Anh', null, array['history','culture','photo']::text[], array['history','quiet','photo']::text[], 120, 0, 30, null, 'leaf', 'Thành cổ hình xoắn ốc, kinh đô nước Âu Lạc của An Dương Vương (thế kỷ 3 TCN), cách trung tâm khoảng 17 km về phía bắc; nhiều di vật văn hoá Đông Sơn.', 'A spiral-walled ancient citadel, capital of King An Duong Vuong’s Au Lac (3rd century BC), about 17 km north of the centre; many Dong Son artefacts.', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, array['https://baovanhoa.vn/di-san/trien-lam-di-tich-quoc-gia-dac-biet-o-ha-noi-59651.html','https://en.wikipedia.org/wiki/C%E1%BB%95_Loa_Citadel']::text[], 'Nhập từ Văn hoá–Giải trí HN (tổng hợp 03/10/2026). Giá là ước tính (nguồn không ghi) — kiểm tra trước khi đi. Toạ độ gần đúng (theo tên đường) — kiểm tra lại. Ngoại thành (~17 km). Bản tiếng Anh do AI dịch.', null, null, null),
  ('den-phu-dong', 'draft', 'hoan-kiem', 'sight', 'quick', 'Đền Phù Đổng', 'Phu Dong Temple', null, 21.05508, 105.96091, 'Phù Đổng, Gia Lâm', null, array['culture','history']::text[], array['cultural','history','quiet']::text[], 60, 0, 20, null, 'brick', 'Đền thờ Thánh Gióng tại quê hương của Gióng; nơi diễn ra Hội Gióng, di sản văn hoá phi vật thể được UNESCO ghi danh.', 'The temple to Saint Giong in his home village, where the Giong Festival — on UNESCO’s intangible heritage list — is held.', null, null, null, null, null, null, 'Ăn mặc kín đáo, nói khẽ, không chụp ảnh người đang lễ.', 'Dress modestly, keep your voice down and don’t photograph people praying.', null, null, null, null, null, null, null, null, null, null, null, null, array['https://baovanhoa.vn/di-san/trien-lam-di-tich-quoc-gia-dac-biet-o-ha-noi-59651.html']::text[], 'Nhập từ Văn hoá–Giải trí HN (tổng hợp 03/10/2026). Giới thiệu theo "hiểu biết chung" (link chỉ xác nhận xếp hạng). Giá là ước tính (nguồn không ghi) — kiểm tra trước khi đi. Ngoại thành. Bản tiếng Anh do AI dịch.', null, null, null),
  ('den-soc-son', 'draft', 'hoan-kiem', 'sight', 'quick', 'Đền Sóc Sơn', 'Soc Son Temple', null, 21.28225, 105.8422, 'Núi Vệ Linh, Sóc Sơn', null, array['culture','history']::text[], array['cultural','history','quiet']::text[], 90, 0, 20, null, 'brick', 'Đền thờ Thánh Gióng trên núi Vệ Linh, tương truyền là nơi Gióng bay về trời; cũng tổ chức Hội Gióng.', 'A temple to Saint Giong on Ve Linh mountain, where legend says he flew up to heaven; it also holds a Giong Festival.', null, null, null, null, null, null, 'Ăn mặc kín đáo, nói khẽ, không chụp ảnh người đang lễ.', 'Dress modestly, keep your voice down and don’t photograph people praying.', null, null, null, null, null, null, null, null, null, null, null, null, array['https://baovanhoa.vn/di-san/trien-lam-di-tich-quoc-gia-dac-biet-o-ha-noi-59651.html']::text[], 'Nhập từ Văn hoá–Giải trí HN (tổng hợp 03/10/2026). Giới thiệu theo "hiểu biết chung". Giá là ước tính (nguồn không ghi) — kiểm tra trước khi đi. Toạ độ gần đúng (theo tên đường) — kiểm tra lại. Ngoại thành (~35 km). Bản tiếng Anh do AI dịch.', null, null, null),
  ('chua-thay', 'draft', 'hoan-kiem', 'sight', 'quick', 'Chùa Thầy', 'Thay Pagoda', null, 21.02294, 105.64545, 'Sài Sơn, Quốc Oai', null, array['culture','history','photo']::text[], array['cultural','quiet','photo']::text[], 120, 0, 20, null, 'leaf', 'Chùa cổ dưới chân núi Sài Sơn, gắn với Thiền sư Từ Đạo Hạnh; có thuỷ đình múa rối nước giữa hồ.', 'An old pagoda at the foot of Sai Son mountain, linked to the monk Tu Dao Hanh, with a water-puppet pavilion in its pond.', null, null, null, null, null, null, 'Ăn mặc kín đáo, nói khẽ, không chụp ảnh người đang lễ.', 'Dress modestly, keep your voice down and don’t photograph people praying.', null, null, null, null, null, null, null, null, null, null, null, null, array['https://baovanhoa.vn/di-san/trien-lam-di-tich-quoc-gia-dac-biet-o-ha-noi-59651.html']::text[], 'Nhập từ Văn hoá–Giải trí HN (tổng hợp 03/10/2026). Giới thiệu theo "hiểu biết chung". Giá là ước tính (nguồn không ghi) — kiểm tra trước khi đi. Ngoại thành (~25 km). Bản tiếng Anh do AI dịch.', null, null, null),
