  ('pose-photo', 'approved', 'hoan-kiem', 'fun', 'quick', 'Pose Photo', 'Pose Photo', null, 21.01647, 105.81485, '33 ngõ 49 Huỳnh Thúc Kháng, Đống Đa', null, array['photo','fun','rainy']::text[], array['photo','indoor','groups']::text[], 20, 50, 120, null, 'butter', 'Photobooth phong cách Hàn, tông hồng ngọt ngào, nằm trong ngõ nhỏ.', 'A Korean-style photobooth in soft pink, tucked down a small alley.', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, array['https://mia.vn/cam-nang-du-lich/photobooth-ha-noi-cuc-hot-19165']::text[], 'Nhập từ Văn hoá–Giải trí HN (tổng hợp 03/10/2026). Giá là ước tính (nguồn không ghi) — kiểm tra trước khi đi. Toạ độ gần đúng (theo tên đường) — kiểm tra lại. Bản tiếng Anh do AI dịch.', null, null, null),
  ('photo-story-chua-lang', 'approved', 'hoan-kiem', 'fun', 'quick', 'Photo Story (Chùa Láng)', 'Photo Story (Chùa Láng)', null, 21.02357, 105.80493, '128 Chùa Láng, Đống Đa', null, array['photo','fun','rainy']::text[], array['photo','indoor','groups']::text[], 20, 50, 120, null, 'butter', 'Photobooth quen thuộc với giới trẻ trên phố Chùa Láng.', 'A photobooth popular with young people on Chua Lang street.', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, array['https://mia.vn/cam-nang-du-lich/photobooth-ha-noi-cuc-hot-19165']::text[], 'Nhập từ Văn hoá–Giải trí HN (tổng hợp 03/10/2026). Giá là ước tính (nguồn không ghi) — kiểm tra trước khi đi. Toạ độ gần đúng (theo tên đường) — kiểm tra lại. Bản tiếng Anh do AI dịch.', null, null, null),
  ('photobooth-dang-van-ngu', 'draft', 'hoan-kiem', 'fun', 'quick', 'Life4cuts & Photo Story (Đặng Văn Ngữ)', 'Life4cuts & Photo Story (Đặng Văn Ngữ)', null, 21.01144, 105.83334, 'Phố Đặng Văn Ngữ, Đống Đa', null, array['photo','fun','rainy']::text[], array['photo','indoor','groups']::text[], 20, 50, 120, null, 'butter', 'Cụm photobooth phong cách tươi trẻ, phù hợp nhóm dưới 6 người; mở cửa đến khoảng 22h.', 'A cluster of youthful photobooths, good for groups under six; open until about 10 pm.', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, array['https://www.greensm.com/vn-vi/news/photobooth-dang-van-ngu-ha-noi']::text[], 'Nhập từ Văn hoá–Giải trí HN (tổng hợp 03/10/2026). Sheet: "nguồn chưa ghi số nhà". Giá là ước tính (nguồn không ghi) — kiểm tra trước khi đi. Toạ độ gần đúng (theo tên đường) — kiểm tra lại. Bản tiếng Anh do AI dịch.', null, null, null)
insert into public.roles (id, name_vi, name_en, intro_vi, intro_en, goal_vi, goal_en, item_noun_vi, item_noun_en, fav_places, fallback_task_vi, fallback_task_en, fallback_item_vi, fallback_item_en, ending_vi, ending_en, tone) values
  ('merchant', 'Thương nhân phố Hàng', 'Hang Street Merchant', 'Bạn vừa từ quê lên kinh với chiếc xe hàng và giấc mơ lớn. Phố cổ có 36 phố phường, mỗi phố một nghề — hãy tìm chỗ đứng của mình.', 'You’ve just arrived from the countryside with a cart and big dreams. The Old Quarter has 36 streets, each selling one thing — find your place among them.', 'Gom đủ {n} món hàng để mở sạp', 'Gather {n} goods to open your stall', 'món hàng', 'goods', array['ma-may-87','dong-xuan','bach-ma','egg-coffee','ta-hien','women-museum','o-quan-chuong','hanoi-post-office']::text[], 'Tìm một chi tiết thật ở đây để có thêm hàng cho sạp.', 'Find a real detail here to earn something for your stall.', 'Một bí quyết buôn bán', 'A trade secret', 'Hàng đã bày đủ, dải lụa đỏ treo trước cửa, sạp hàng nhỏ của bạn mở trên một phố Hàng. Hàng xóm ghé qua chúc may mắn — bạn không còn là người mới đến, bạn đã là một phần của phố cổ.', 'With your goods laid out and a red ribbon over the door, your little stall opens on a Hang street. The neighbours come by to wish you luck — you are no longer a newcomer, you are part of the Old Quarter.', 'butter'),
  ('scholar', 'Sĩ tử lên kinh', 'Scholar Bound for the Capital', 'Bạn đã đi bộ nhiều tuần để lên Thăng Long ứng thí. Trước khi cổng trường thi mở, bạn phải thu thập phúc lành và trí tuệ của kinh thành.', 'You’ve walked for weeks to sit the royal exam in Thang Long. Before the exam gate opens, you must gather the blessings and wisdom of the capital.', 'Gom {n} bảo vật để vào trường thi', 'Collect {n} treasures to enter the exam hall', 'bảo vật', 'treasures', array['ngoc-son','the-huc','turtle-tower','bach-ma','hoa-lo','women-museum','quan-su-pagoda','imperial-citadel','48-hang-ngang']::text[], 'Quan sát thật kỹ — sĩ tử giỏi là người để ý chi tiết.', 'Observe carefully — a true scholar notices the details.', 'Một trang ghi chép', 'A page of notes', 'Trống điểm, cổng trường thi mở. Với cây bút, trang ghi chép và phúc lành của kinh thành, bạn ngồi vào lều thi. Dù kết quả thế nào, bạn đã học được điều kinh thành muốn dạy.', 'The drum sounds and the exam gate opens. With your brush, your notes and the blessings of the capital, you take your seat. Whatever the result, you have learned what the city had to teach.', 'teal'),
  ('photographer', 'Nhiếp ảnh gia thập niên 1930', '1930s Photographer', 'Những năm 1930. Bạn vừa mua chiếc máy ảnh đầu tiên cùng vài tấm kính phim. Một tờ báo Hà Thành sẽ in triển lãm của bạn — nếu bạn mang về đúng những khung hình.', 'It’s 1930-something. You’ve bought your first camera with a handful of glass plates. A Hanoi newspaper will print your exhibition — if you bring the right shots.', 'Chụp đủ {n} khung hình cho triển lãm', 'Capture {n} frames for your exhibition', 'khung hình', 'frames', array['the-huc','cathedral','turtle-tower','dong-xuan','ngoc-son','hoa-lo','opera-house','hoa-phong-tower','o-quan-chuong']::text[], 'Tìm một chi tiết kể được câu chuyện của nơi này.', 'Find the one detail that tells this place’s story.', 'Khung hình đường phố', 'A street frame', 'Những tấm kính phim được tráng rửa và treo lên tường toà báo. Người đọc dừng lại trước từng tấm — họ nhận ra chính con phố của mình. Chín mươi năm sau, bạn vừa chụp lại đúng những khung hình ấy.', 'Your glass plates are developed and pinned on the newspaper’s wall. Readers stop in front of them — they recognise their own streets. Ninety years later, you have just taken the same photos again.', 'brick'),
  ('chef', 'Đầu bếp tập sự', 'Apprentice Cook', 'Sư phụ giao cho bạn chiếc giỏ trống và bảo vào phố cổ. Muốn nấu mâm cỗ đầu tiên, bạn phải học hương vị Hà Nội từ chính những người làm ra nó.', 'Your master sent you into the Old Quarter with an empty basket. To cook your first feast, you must learn the city’s flavours from those who made them.', 'Gom {n} nguyên liệu cho mâm cỗ đầu tiên', 'Gather {n} ingredients for your first feast', 'nguyên liệu', 'ingredients', array['bun-cha','egg-coffee','dong-xuan','ta-hien','ma-may-87','water-puppets','ly-thai-to-park']::text[], 'Nơi nào cũng có một hương vị. Tìm chi tiết ẩn giấu nó.', 'Every place has a flavour. Find the detail that hides it.', 'Một chút vị Hà Nội', 'A pinch of Hanoi', 'Trở về bếp, bạn bày ra tất cả những gì đã gom được. Sư phụ nếm thìa đầu tiên, lặng đi một lúc rồi gật đầu: “Giờ con nấu như người đã đi qua từng con phố ấy.”', 'Back in the kitchen, you lay out everything you gathered. Your master tastes the first spoonful, pauses, and nods. “Now you cook like someone who has walked these streets.”', 'leaf')
insert into public.missions (role_id, place_id, status, task_vi, task_en, item_vi, item_en) values
  ('merchant', 'ma-may-87', 'approved', 'Học cách một gia đình buôn bán xưa bày hàng ở gian trước.', 'Learn how an old merchant family set up shop at the front of the house.', 'Tấm biển hiệu', 'A shop signboard'),
  ('merchant', 'dong-xuan', 'approved', 'Tìm nơi dân buôn sỉ tụ họp và lấy được lòng tin của họ.', 'Find where wholesale traders gather and earn their trust.', 'Một súc lụa', 'A bolt of silk'),
  ('merchant', 'bach-ma', 'approved', 'Xin thần trấn phía Đông phù hộ cho việc buôn bán.', 'Ask the guardian of the east for a blessing on your trade.', 'Dải lụa đỏ may mắn', 'A lucky red ribbon'),
  ('merchant', 'egg-coffee', 'approved', 'Khám phá cách một người buôn khéo vượt qua lúc thiếu sữa.', 'Discover how a clever trader beat the milk shortage.', 'Công thức bí truyền', 'A secret recipe'),
  ('merchant', 'ta-hien', 'approved', 'Ngồi cùng phố một ly và nghe giá cả trong ngày.', 'Share a drink with the street and hear the day’s prices.', 'Một mối khách quen', 'A regular customer'),
  ('merchant', 'women-museum', 'approved', 'Học mẹo của các chị hàng rong vào phố từ tờ mờ sáng.', 'Learn the tricks of the street vendors who walk in before dawn.', 'Chiếc đòn gánh', 'A bamboo shoulder pole'),
  ('scholar', 'ngoc-son', 'approved', 'Thắp hương thần Văn Xương và đọc chữ trên Tháp Bút.', 'Pray to the god of literature and read the words on the Pen Tower.', 'Cây bút lông', 'A calligraphy brush'),
  ('scholar', 'the-huc', 'approved', 'Bước qua cầu ánh ban mai với tâm trí sáng suốt.', 'Cross the bridge of morning light with a clear mind.', 'Tia nắng ban mai', 'A ray of morning light'),
  ('scholar', 'turtle-tower', 'approved', 'Nghe truyền thuyết trả gươm — bài học về sự khiêm nhường.', 'Learn the legend of the returned sword — a lesson in humility.', 'Phúc lành của Rùa Vàng', 'The golden turtle’s blessing'),
  ('scholar', 'bach-ma', 'approved', 'Tìm hiểu thành Thăng Long được vạch ra như thế nào.', 'Find out how the capital’s walls were first traced.', 'Bản đồ kinh thành', 'A map of the citadel'),
  ('scholar', 'hoa-lo', 'approved', 'Tưởng nhớ những người vẫn học, vẫn viết sau song sắt.', 'Remember those who studied and wrote even behind prison walls.', 'Cuốn sổ bí mật', 'A hidden notebook'),
  ('scholar', 'women-museum', 'approved', 'Hiểu sự hy sinh của ai đã giúp sĩ tử lên được kinh thành.', 'Learn whose sacrifices let a scholar travel to the capital.', 'Lá thư của mẹ', 'A mother’s letter'),
  ('photographer', 'the-huc', 'approved', 'Chờ ánh sáng đậu trên dáng cầu đỏ rồi bấm máy.', 'Wait for the light to rest on the red curve, then shoot.', 'Khung hình: cây cầu đỏ', 'Frame: the red bridge'),
  ('photographer', 'cathedral', 'approved', 'Chụp đôi tháp chuông Pháp mới xây cho tờ báo.', 'Photograph the new French-built towers for the newspaper.', 'Khung hình: đôi tháp chuông', 'Frame: the twin towers'),
  ('photographer', 'turtle-tower', 'approved', 'Chụp ngọn tháp trên mặt nước lặng, như huyền thoại ngưng đọng.', 'Capture the tower in still water, like a legend frozen in time.', 'Khung hình: hồ trả gươm', 'Frame: the returned sword'),
  ('photographer', 'dong-xuan', 'approved', 'Tìm khoảnh khắc đông vui nhất của chợ và giữ nó lại.', 'Find the market’s busiest moment and freeze it.', 'Khung hình: chợ lớn', 'Frame: the great market'),
  ('photographer', 'ngoc-son', 'approved', 'Chụp ngọn Tháp Bút viết lên trời xanh.', 'Photograph the Pen Tower that writes on the sky.', 'Khung hình: Tháp Bút', 'Frame: the Pen Tower'),
  ('photographer', 'hoa-lo', 'approved', 'Ghi lại cổng nhà tù mà báo chí không dám nhắc tới.', 'Document the prison gate the newspapers won’t talk about.', 'Khung hình: cánh cổng sắt', 'Frame: the iron gate'),
  ('chef', 'bun-cha', 'approved', 'Học bí quyết bát nước chấm — chua, ngọt, mặn, thơm khói.', 'Learn the secret of the dipping broth — sweet, sour, salty, smoky.', 'Làn khói than hoa', 'Charcoal smoke'),
  ('chef', 'egg-coffee', 'approved', 'Xem lòng đỏ và đường biến thành kem như thế nào.', 'Watch how yolk and sugar become cream.', 'Kem trứng vàng', 'Golden egg cream'),
  ('chef', 'dong-xuan', 'approved', 'Tìm rau thơm tươi nhất ở ngõ sau chợ.', 'Find the freshest herbs in the market’s back alley.', 'Bó rau thơm', 'A bundle of fresh herbs'),
  ('chef', 'ta-hien', 'approved', 'Nếm thử món nhắm buổi tối của phố.', 'Taste what the street snacks on in the evening.', 'Món nhắm vỉa hè', 'A street snack'),
  ('chef', 'ma-may-87', 'approved', 'Tìm gian bếp của nhà cổ và xem một gia đình xưa nấu nướng.', 'Find the kitchen of the old house and see how a family cooked.', 'Chiếc niêu đất', 'A family clay pot'),
  ('chef', 'water-puppets', 'approved', 'Xem cảnh đồng lúa — nơi mọi bữa cơm bắt đầu.', 'Watch the rice-field scenes — where every meal begins.', 'Nắm gạo mới', 'A handful of new rice'),
  ('merchant', 'o-quan-chuong', 'approved', 'Đi qua cửa ô phía Đông nơi hàng hoá từ bến sông vào phố – và đọc lệnh cấm sách nhiễu người qua lại.', 'Pass the east gate where goods came up from the river — and read the rule that protected traders.', 'Tấm thẻ qua cửa ô', 'A gate pass'),
  ('merchant', 'hanoi-post-office', 'approved', 'Tìm nơi tin tức và đơn hàng từ khắp xứ được truyền về bằng điện tín.', 'Find where news and orders from the whole country arrived by wire.', 'Bức điện tín của mối hàng', 'A telegram from a buyer'),
  ('scholar', 'quan-su-pagoda', 'approved', 'Tìm hiểu kinh thành đón tiếp sứ thần ra sao – bài học về bang giao.', 'Learn how the capital welcomed foreign envoys — a lesson in diplomacy.', 'Ấn tín của sứ thần', 'An envoy''s seal'),
  ('scholar', 'imperial-citadel', 'approved', 'Bước qua Đoan Môn, cánh cổng mọi vị quan phải đi qua để vào chầu vua.', 'Walk through Doan Mon, the gate every official passed to reach the king.', 'Dải đai triều phục', 'A court robe sash'),
  ('scholar', '48-hang-ngang', 'approved', 'Tìm chiếc bàn nhỏ nơi những lời đầu tiên của một đất nước mới được viết ra.', 'Find the small table where a new country''s first words were written.', 'Trang giấy đánh máy', 'A typed page'),
  ('photographer', 'opera-house', 'approved', 'Chụp Nhà hát Lớn mới khánh thành cho số báo buổi chiều.', 'Photograph the brand-new Opera House for the evening edition.', 'Khung hình: mặt tiền Nhà hát', 'Frame: the Opera facade'),
  ('photographer', 'hoa-phong-tower', 'approved', 'Ghi lại mảnh cuối cùng của một ngôi chùa lớn trước khi nó bị lãng quên.', 'Capture the last piece of a great pagoda before it is forgotten.', 'Khung hình: ngọn tháp đơn độc', 'Frame: the lone tower'),
  ('photographer', 'o-quan-chuong', 'approved', 'Chụp cửa ô cổ với dòng người qua lại.', 'Shoot the old city gate with life passing through it.', 'Khung hình: cửa ô phía Đông', 'Frame: the east gate'),
  ('chef', 'ly-thai-to-park', 'approved', 'Quan sát người tập buổi sáng và tìm hiểu Hà Nội ăn gì trước 7 giờ.', 'Watch the morning crowd and learn what Hanoi eats before 7 am.', 'Bí mật bữa sáng', 'A breakfast secret')
