  ('mua-roi-thang-long', 'draft', 'hoan-kiem', 'show', 'theatre', 'ok', 'Múa rối nước Thăng Long', 'Thang Long Water Puppet Show', 'Suất diễn khoảng 50 phút với dàn nhạc dân tộc sống và những con rối gỗ lướt trên mặt nước.', 'A roughly 50-minute show with a live folk orchestra and wooden puppets gliding across the water.', 'water-puppets', 'Nhà hát Múa rối Thăng Long', '57B Đinh Tiên Hoàng', 21.0318, 105.8535, '2026-01-01', '2027-12-31', '{}'::text[], array['15:00','16:10','17:20','18:30','20:00']::text[], null, 50, 100, 200, true, null, null, null, 'Biên tập', '2026-10-03', 'Mẫu cho sự kiện lặp lại nhiều suất/ngày. Cần đối chiếu lịch diễn, giá vé, toạ độ và link chính thức của nhà hát trước khi duyệt.', true),
  ('pho-di-bo-ho-guom', 'approved', 'hoan-kiem', 'open', 'festival', 'ok', 'Phố đi bộ Hồ Gươm', 'Hoan Kiem Walking Street', 'Tối cuối tuần, các phố quanh hồ cấm xe: trò chơi dân gian, nhạc đường phố và cả gia đình dạo bộ.', 'On weekend evenings the streets around the lake close to traffic: folk games, street music and families out for a stroll.', null, 'Quanh Hồ Hoàn Kiếm', 'Đinh Tiên Hoàng, Lê Thái Tổ, Hàng Khay', 21.0287, 105.8524, '2026-01-01', '2027-12-31', array['fri','sat','sun']::text[], array['19:00']::text[], '23:59', 60, 0, 0, false, null, null, null, 'Biên tập', '2026-10-03', 'Khung giờ theo quy định phố đi bộ (T6 19h → hết CN); app chỉ gợi ý buổi tối. Kiểm tra lịch tạm dừng dịp lễ.', true),
